INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('non_verbal', '損益算', NULL, '定価2000円の商品を3割引で売ったところ、原価に対して2割の利益が出た。この商品の原価はいくらか。', NULL, '["1000円","1100円","1167円","1200円","1400円"]', 2, '["売価 = 定価2000円 × (1 - 0.3) = 1400円","売価は原価に2割の利益を乗せた額なので、原価 × 1.2 = 1400円","原価 = 1400 ÷ 1.2 = 約1167円"]', 3, 'published', 'src/data/questions.tsからの移設（自作問題）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('non_verbal', '推論', NULL, 'A, B, C, D の4人が徒競走をした。Aは Bより先にゴールし、Cは Aより先にゴールした。Dは Bより後にゴールした。このとき、必ず正しいといえるのはどれか。', NULL, '["Cが1位である","Dが最下位である","Cは Bより先にゴールした","Aは Dより先にゴールした","順位は一意に確定する"]', 2, '["条件を整理すると、C → A → B（Cが先、Aが次、Bが後）","また D → B の後、つまり B → D","これらをつなげると C → A → B → D となる","よって Cは Bより必ず先にゴールしている（選択肢C）","Dの位置はBより後という情報のみで最下位確定ではないため選択肢Bは誤り"]', 3, 'published', 'src/data/questions.tsからの移設（自作問題）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('non_verbal', '損益算', NULL, '原価800円の商品に4割の利益を見込んで定価をつけたが、売れなかったため定価の2割引で販売した。この商品の利益（円）はいくらか。', NULL, '["48円","96円","112円","128円","160円"]', 1, '["定価 = 原価800円 × (1 + 0.4) = 1120円","販売価格 = 定価1120円 × (1 - 0.2) = 896円","利益 = 販売価格896円 - 原価800円 = 96円"]', 3, 'published', 'src/data/questions.tsからの移設（自作問題）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('non_verbal', '資料の読み取り', '料金表の読み取り（宅配便）', 'ある運送会社は、料金が荷物の重さによって決まっている。各重さによる配送料金は以下の表の通りである。
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('non_verbal', '資料の読み取り', '資料解釈（複数表の比較）', '都市P、Q、Rの1年間の図書館利用者数を調べた。
